public PaymentResponse processPayment(PaymentRequest request, String idempotencyKey) {

    String key = "idem:" + idempotencyKey;

    // Step 1: Check whether the request already exists

    IdempotencyRecord existing =
            redisTemplate.opsForValue().get(key);

    if (existing != null) {

        // Request is still being processed
        if (existing.isInFlight()) {
            throw new ResponseStatusException(
                   HttpStatus.CONFLICT,
                    "Request already in progress"
            );
        }

        // Request already completed, return cached response
        return (PaymentResponse) existing.getResponse();
    }

    // Step 2: Acquire an atomic lock using Redis SET NX

    Boolean acquired =
            redisTemplate.opsForValue().setIfAbsent(
                    key,
                    IdempotencyRecord.inProgress(),
                    Duration.ofMinutes(5)
            );

    if (Boolean.FALSE.equals(acquired)) {
        throw new ResponseStatusException(
                HttpStatus.CONFLICT,
                "Duplicate request"
        );
    }

    try {

        // Step 3: Execute the business logic

        PaymentResponse response =
                paymentService.processPayment(request);

        // Step 4: Store the successful response

        IdempotencyRecord completed =
                new IdempotencyRecord(
                        HttpStatus.OK.value(),
                        response,
                        false
                );

        redisTemplate.opsForValue().set(
                key,
                completed,
                Duration.ofHours(24)
        );

        // Step 5: Return the response

        return response;

    } catch (Exception ex) {

        // Step 6: Store the failed response

        ErrorResponse error =
                new ErrorResponse("Payment Failed");

        IdempotencyRecord failed =
                new IdempotencyRecord(
                        HttpStatus.INTERNAL_SERVER_ERROR.value(),
                        error,
                        false
                );

        redisTemplate.opsForValue().set(
                key,
                failed,
                Duration.ofHours(24)
        );

        throw ex;
    }
}

